func (n *TipranksNamespace) Analysts(ctx context.Context, q TipRanksAnalystsQuery) ([]TipRanksAnalystProfile, error) {
	params, err := q.params()
	if err != nil {
		return nil, err
	}
	var out []TipRanksAnalystProfile
	if err := n.client.getJSON(ctx, "tipranks-analysts", "tipranks-analysts", params, &out); err != nil {
		return nil, err
	}
	return out, nil
}
